'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { parse, stringify, CsvError } = require('../src/csv');

const fails = (fn, line, column) =>
  assert.throws(fn, (e) => e instanceof CsvError && e instanceof Error && e.line === line && e.column === column);

test('parse basics', () => {
  assert.deepEqual(parse(''), []);
  assert.deepEqual(parse('a,b\r\nc,d\ne,f\rg,h'), [['a', 'b'], ['c', 'd'], ['e', 'f'], ['g', 'h']]);
  assert.deepEqual(parse('﻿a,b'), [['a', 'b']]);
  assert.deepEqual(parse(' a , b ,'), [[' a ', ' b ', '']]);
  assert.deepEqual(parse('a;b', { delimiter: ';' }), [['a', 'b']]);
  assert.deepEqual(parse('a"b,c"'), [['a"b', 'c"']]);
});

test('parse quoting', () => {
  assert.deepEqual(parse('"a,b","c""d","e\r\nf"\n'), [['a,b', 'c"d', 'e\r\nf']]);
  assert.deepEqual(parse('""'), [['']]);
  assert.deepEqual(parse('"a"\n"b"'), [['a'], ['b']]);
});

test('parse empty lines', () => {
  assert.deepEqual(parse('a\n'), [['a']]);
  assert.deepEqual(parse('\n'), [['']]);
  assert.deepEqual(parse('a\n\nb\n\n'), [['a'], [''], ['b'], ['']]);
  assert.deepEqual(parse('a\n\nb\n\n', { skipEmptyLines: true }), [['a'], ['b']]);
  assert.deepEqual(parse('""\n', { skipEmptyLines: true }), [['']]);
});

test('parse input validation', () => {
  for (const bad of [null, undefined, 1, {}, Buffer.from('a')]) assert.throws(() => parse(bad), TypeError);
  for (const d of ['', ',,', '"', '\r', '\n', 1]) assert.throws(() => parse('a', { delimiter: d }), TypeError);
});

test('parse error positions', () => {
  fails(() => parse('a,b\nc,"oops\n'), 2, 3);
  fails(() => parse('a,"x"y'), 1, 6);
  fails(() => parse('"a\nb"x'), 2, 3);
  fails(() => parse('"'), 1, 1);
});

test('parse header mode', () => {
  assert.deepEqual(parse('a,b\n1,2\n3,4', { header: true }), [{ a: '1', b: '2' }, { a: '3', b: '4' }]);
  assert.deepEqual(parse('a,b\n', { header: true }), []);
  assert.deepEqual(parse('__proto__\nx', { header: true }).map((o) => Object.keys(o)), [['__proto__']]);
  fails(() => parse('a,b,a\n1,2,3', { header: true }), 1, 5);
  fails(() => parse('a,"b"\n1,2\nx,y\n"q",""z', { header: true }), 4, 8);
  fails(() => parse('a,b\n1,2\n3', { header: true }), 3, 1);
  fails(() => parse('a,b\n1,2,3', { header: true }), 2, 1);
  fails(() => parse('a,\n"b\n",b\nb', { header: true }), 1, 1 + 0 || 1);
});

test('stringify basics', () => {
  assert.equal(stringify([]), '');
  assert.equal(stringify([['a', 1, true, null, undefined]]), 'a,1,true,,\r\n');
  assert.equal(stringify([['a', 'b']], { eol: '\n' }), 'a,b\n');
  assert.equal(stringify([['a;b', 'c,d']], { delimiter: ';' }), '"a;b";c,d\r\n');
  assert.equal(stringify([['a,b', 'q"r', ' x', 'y ', 'l\nm', 'c\rd']]), '"a,b","q""r"," x","y ","l\nm","c\rd"\r\n');
  assert.equal(stringify([['']]), '""\r\n');
  assert.equal(stringify([['', '']]), ',\r\n');
});

test('stringify header and errors', () => {
  assert.equal(stringify([{ a: 1, b: 'x' }, { b: 'y' }, ['p', 'q']], { header: ['a', 'b'] }), 'a,b\r\n1,x\r\n,y\r\np,q\r\n');
  assert.equal(stringify([], { header: ['a'] }), 'a\r\n');
  assert.throws(() => stringify('x'), TypeError);
  assert.throws(() => stringify([{ a: 1 }]), TypeError);
  assert.throws(() => stringify([['a']], { eol: '\r' }), TypeError);
  assert.throws(() => stringify([['a']], { delimiter: '"' }), TypeError);
  assert.throws(() => stringify([[{}]]), TypeError);
  assert.throws(() => stringify([[1n]]), TypeError);
  assert.throws(() => stringify([[() => 1]]), TypeError);
  assert.throws(() => stringify([null]), TypeError);
});

test('round trip', () => {
  const samples = [[['']], [[''], ['']], [['a', ''], ['', '']], [[' ', '"', '""'], ['\r', '\n', '\r\n']], [['é😀', ',']], [['a'], [''], ['b']]];
  for (const opts of [{}, { skipEmptyLines: true }, { delimiter: '\t', eol: '\n' }]) {
    for (const rows of samples) assert.deepEqual(parse(stringify(rows, opts), opts), rows);
  }
});
